const $=s=>document.querySelector(s);
const dialog=$('#game-dialog'),content=$('#game-content');
let records=Object.create(null);try{const raw=JSON.parse(localStorage.getItem('chem-club-records')||'{}');for(const key of ['quiz','balance','builder']){const r=raw?.[key],total=key==='quiz'?5:3;if(r&&Number.isSafeInteger(r.best)&&r.best>=0&&r.best<=total&&r.total===total&&Number.isSafeInteger(r.plays)&&r.plays>=0&&r.plays<Number.MAX_SAFE_INTEGER)records[key]={best:r.best,total,plays:r.plays};}}catch{}
const names={quiz:'너의 이름은, 원소.',balance:'모든 반응에는 균형이.',builder:'함께라서, 새로운 세계.'};
const quizzes=[['O','산소',['산소','금','수소','탄소'],'산소의 원자 번호는 8이에요.'],['Na','나트륨',['질소','네온','나트륨','니켈'],'Na는 라틴어 Natrium에서 왔어요.'],['Fe','철',['플루오린','철','금','은'],'철의 기호 Fe는 라틴어 Ferrum에서 왔어요.'],['Au','금',['은','아르곤','알루미늄','금'],'금의 원자 번호는 79예요.'],['C','탄소',['칼슘','염소','탄소','구리'],'탄소는 생명체를 구성하는 주요 원소예요.']];
const reactions=[{parts:['H₂','O₂','H₂O'],answer:[2,1,2],hint:'양쪽의 H 원자 수와 O 원자 수가 같아야 해요.'},{parts:['N₂','H₂','NH₃'],answer:[1,3,2],hint:'N을 먼저 맞추고, H 원자를 세어보세요.'},{parts:['Fe','O₂','Fe₂O₃'],answer:[4,3,2],hint:'O 원자 수를 6개로 맞추면 쉬워요.'}];
const molecules=[{name:'물',formula:'H₂O',atoms:{H:2,O:1}},{name:'이산화 탄소',formula:'CO₂',atoms:{C:1,O:2}},{name:'암모니아',formula:'NH₃',atoms:{N:1,H:3}}];
let mode,index,score,locked,selected;
function open(){if(!dialog.open)dialog.showModal();}
$('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));let count=0;document.querySelectorAll('.game-row').forEach(row=>{row.hidden=b.dataset.filter!=='all'&&row.dataset.level!==b.dataset.filter;if(!row.hidden)count++;});$('#filter-status').textContent=`${count}개의 실험이 기다리고 있어요.`;});
document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>start(b.dataset.game));
function start(game){mode=game;index=0;score=0;open();render();}
function render(){locked=false;selected={};const total=mode==='quiz'?5:3;$('#dialog-label').textContent=`${mode.toUpperCase()} / ${index+1} OF ${total}`;let html=`<h2>${names[mode]}</h2>`;
if(mode==='quiz'){const q=quizzes[index];html+=`<p>이 기호는 어떤 원소일까요?</p><span class="symbol">${q[0]}</span><div class="choices">${q[2].map(x=>`<button data-answer="${x}">${x}</button>`).join('')}</div>`;}
if(mode==='balance'){const q=reactions[index];html+=`<p>가장 작은 양의 정수 계수로 균형을 맞춰보세요.</p><div class="balance-inputs">${q.parts.map((x,i)=>`${i===1?'<span>+</span>':i===2?'<span>→</span>':''}<label><input type="number" min="1" max="20" step="1" value="1" aria-label="${x} 계수">${x}</label>`).join('')}</div><p class="quiet">${q.hint}</p><button class="dialog-action" id="check">균형 확인하기</button>`;}
if(mode==='builder'){const q=molecules[index];html+=`<p><strong>${q.name} (${q.formula})</strong> 분자를 만들어보세요.<br>버튼을 눌러 필요한 수만큼 원자를 더하세요.</p><div class="assembled" id="assembled" aria-live="polite">원자를 골라주세요</div><div class="atom-controls">${['H','O','C','N'].map(x=>`<button data-atom="${x}">+ ${x}</button>`).join('')}<button id="clear-atoms">비우기</button></div><button class="dialog-action" id="check">분자 확인하기</button>`;}
content.innerHTML=html+'<p class="feedback" id="feedback" role="status"></p><button class="dialog-action" id="next" hidden>다음 발견 →</button>';
if(mode==='quiz')document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(locked)return;locked=true;const q=quizzes[index],ok=b.dataset.answer===q[1];if(ok)score++;feedback(ok,`${ok?'정답이에요!':'정답은 '+q[1]+'예요.'} ${q[3]}`);document.querySelectorAll('[data-answer]').forEach(x=>{x.disabled=true;if(x.dataset.answer===q[1])x.style.borderColor='#8052ff';});$('#next').hidden=false;});
if(mode==='balance')$('#check').onclick=()=>{if(locked)return;const values=[...content.querySelectorAll('input')].map(x=>Number(x.value));const ok=values.every((x,i)=>x===reactions[index].answer[i]);if(ok){score++;locked=true;$('#check').disabled=true;$('#next').hidden=false;feedback(true,'완벽한 균형이에요! 양쪽의 원자 수가 같아요.');}else feedback(false,'아직 균형이 맞지 않아요. 가장 작은 정수 계수로 다시 도전해보세요.');};
if(mode==='builder'){document.querySelectorAll('[data-atom]').forEach(b=>b.onclick=()=>{if(locked)return;const a=b.dataset.atom;selected[a]=Math.min((selected[a]||0)+1,9);updateAtoms();});$('#clear-atoms').onclick=()=>{if(locked)return;selected={};updateAtoms();};$('#check').onclick=()=>{if(locked)return;const target=molecules[index].atoms;const ok=['H','O','C','N'].every(x=>(selected[x]||0)===(target[x]||0));if(ok){score++;locked=true;$('#check').disabled=true;$('#next').hidden=false;feedback(true,`${molecules[index].name} 완성! 원자들의 새로운 연결을 발견했어요.`);}else feedback(false,'원자의 종류와 개수를 확인해보세요. 비우고 다시 조립할 수 있어요.');};}
$('#next').onclick=()=>{index++;if(index===total)finish(total);else render();};}
function updateAtoms(){$('#assembled').textContent=Object.entries(selected).map(([x,n])=>x+(n>1?'₀₁₂₃₄₅₆₇₈₉'[n]:'')).join(' ')||'원자를 골라주세요';}
function feedback(ok,text){const el=$('#feedback');el.className='feedback '+(ok?'good':'bad');el.textContent=text;}
function finish(total){const old=records[mode]||{best:0,plays:0};records[mode]={best:Math.max(old.best,score),plays:old.plays+1,total};let saved=true;try{localStorage.setItem('chem-club-records',JSON.stringify(records));}catch{saved=false;}$('#dialog-label').textContent='EXPERIMENT COMPLETE';content.innerHTML=`<h2>오늘도 새로운 발견.</h2><div class="score-big">${score}<span style="font-size:24px;color:#9a9a9a"> / ${total}</span></div><p>${mode==='quiz'?'맞힌 원소의 개수예요. 다시 도전해 더 많은 원소를 발견해보세요.':'모든 도전을 완성했어요! 시행착오도 발견의 일부예요.'}</p><p class="quiet">${saved?'실험 기록이 이 브라우저에 저장되었어요.':'브라우저 저장소를 사용할 수 없어 이번 기록은 현재 창에서만 유지돼요.'}</p><button id="again" class="dialog-action">다시 도전하기 ↗</button>`;$('#again').onclick=()=>start(mode);}
$('#record-link').onclick=()=>{open();$('#dialog-label').textContent='YOUR DISCOVERIES';content.innerHTML='<h2>나의 실험 기록</h2><p>이 브라우저에서 완성한 실험과 최고 기록이에요.</p>'+Object.entries(names).map(([key,name])=>`<div class="record-item"><span>${name}</span><span>${records[key]?`${records[key].best} / ${records[key].total} · ${records[key].plays}회 완료`:'아직 발견 전'}</span></div>`).join('')+'<p class="quiet">반응식과 분자 조립은 다시 시도하며 완성하는 게임이에요.<br>원소 퀴즈는 첫 답변을 기준으로 점수를 기록해요.</p>';};
// Deterministic triangular particle cloud: three atomic orbitals and a nucleus.
const canvas=$('#constellation'),ctx=canvas.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let width=0,height=0,seed=1729;function rand(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646;}
const palette=['#8052ff','#b477ff','#ffb829','#15846e','#4fb6bb','#e25db5','#6e80ff'];
const particles=Array.from({length:1900},(_,i)=>{const angle=rand()*Math.PI*2,orbit=i%3,tilt=orbit*Math.PI/3;let x,y,z;if(i<1500){const a=.38+(rand()-.5)*.09,b=.115+(rand()-.5)*.075;x=Math.cos(angle)*a;y=Math.sin(angle)*b;z=Math.sin(angle)*.13;const xx=x*Math.cos(tilt)-y*Math.sin(tilt);y=x*Math.sin(tilt)+y*Math.cos(tilt);x=xx;}else{const r=Math.pow(rand(),.5)*.115;x=Math.cos(angle)*r;y=Math.sin(angle)*r;z=rand()*.1;}return{x,y,z,color:palette[Math.floor(rand()*palette.length)],size:.5+rand()*1.5,phase:rand()*6.28};});
const ambient=Array.from({length:60},()=>({x:rand(),y:rand(),color:palette[Math.floor(rand()*palette.length)],size:rand()+.7}));
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
function triangle(x,y,size,color,alpha){ctx.globalAlpha=alpha;ctx.strokeStyle=color;ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(x,y-size);ctx.lineTo(x+size*.86,y+size*.5);ctx.lineTo(x-size*.86,y+size*.5);ctx.closePath();ctx.stroke();}
function draw(t){ctx.clearRect(0,0,width,height);const time=reduced?0:t*.00013;ambient.forEach(p=>triangle(p.x*width,p.y*height,p.size,p.color,.3));const scale=Math.min(width,height)*1.12;particles.forEach(p=>{const x=p.x*Math.cos(time*.35)+p.z*Math.sin(time*.35),y=p.y+Math.sin(time+p.phase)*.006;triangle(width*.5+x*scale,height*.48+y*scale,p.size,p.color,.4+.5*(.5+.5*Math.sin(time*2+p.phase)));});ctx.globalAlpha=1;if(!reduced)requestAnimationFrame(draw);}
new ResizeObserver(()=>{resize();if(reduced)draw(0);}).observe(canvas);resize();requestAnimationFrame(draw);
